<?php
require_once 'panel_common.php';panelSchema();
if($_SERVER['REQUEST_METHOD']==='POST') {
    $data=panelInput();$id=filter_var($data['id']??null,FILTER_VALIDATE_INT);$rate=$data['multiplier']??null;
    if($id===false||!is_numeric($rate)||!is_finite((float)$rate)||$rate<0||$rate>100)panelReply(['error'=>'Hệ số phải từ 0 đến 100'],422);
    $stmt=$conn->prepare('SELECT id FROM skill_template WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();if(!$stmt->get_result()->fetch_assoc())panelReply(['error'=>'Skill không tồn tại'],404);
    $stmt=$conn->prepare('INSERT INTO panel_skill_rate(skill_id,multiplier) VALUES(?,?) ON DUPLICATE KEY UPDATE multiplier=VALUES(multiplier)');$stmt->bind_param('id',$id,$rate);$stmt->execute();panelReply(['message'=>'Đã lưu. Server nhận trong khoảng 3 giây. Đặt x1 để về gốc.']);
}
$skills=$conn->query('SELECT s.id,s.name,COALESCE(r.multiplier,1) AS multiplier FROM skill_template s LEFT JOIN panel_skill_rate r ON r.skill_id=s.id ORDER BY s.id')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><link rel="stylesheet" href="panel.css"><style>body{padding:18px;background:#faffff}input{width:90px;padding:7px;border:1px solid #b9cedd}h1{font-size:16px}form{display:flex;gap:8px}</style></head><body><h1>⚔ Chỉnh Dame Skill</h1><p class="hint">Hệ số áp dụng cho sát thương skill của người chơi tại hàm tính dame. x1 giữ nguyên, x2 gấp đôi, x0 không gây dame. Áp dụng cả Ma Kankō Sappō, Quả cầu kênh khí và Tự phát nổ; hệ số giữ nguyên các điều kiện skill và không thay đổi dame boss. Skill hỗ trợ không có sát thương để nhân.</p><p id="result" role="status"></p><table><thead><tr><th>Skill</th><th>Hệ số dame</th></tr></thead><tbody><?php foreach($skills as $s):?><tr><td><?=panelEscape($s['name'])?> (#<?=$s['id']?>)</td><td><form data-id="<?=$s['id']?>"><input aria-label="Hệ số <?=panelEscape($s['name'])?>" type="number" value="<?=$s['multiplier']?>" min="0" max="100" step="0.01" required><button class="primary">Lưu</button><button type="button" class="secondary" onclick="this.form.querySelector('input').value=1">Về gốc x1</button></form></td></tr><?php endforeach;?></tbody></table><script>const csrf=<?=json_encode($_SESSION['panel_csrf'])?>;document.querySelectorAll('form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const r=await fetch('skill_rates.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,id:Number(form.dataset.id),multiplier:Number(form.querySelector('input').value)})});const j=await r.json();document.getElementById('result').textContent=j.error||j.message;}catch(e){document.getElementById('result').textContent='Không thể kết nối';}finally{b.disabled=false;}});</script></body></html>
